mapper.select:
SELECT TRANSACTION_ID as transactionId, TRANSACTION_NO as transactionNo, TRANSACTION_TYPE as transactionType, TRANSACTION_DATE as transactionDate, BUSINESS_DATA as businessData, SOURCE_SYSTEM as sourceSystem, TRANSACTION_STATUS as transactionStatus, BOOK_ID as bookId, TENANT_ID as tenantId, VERSION as version, CREATE_TIME as createTime, UPDATE_TIME as updateTime, CREATOR as creator, UPDATER as updater FROM T_BUSINESS_TRANSACTION WHERE IS_DELETED = 0
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
AND TRANSACTION_NO LIKE CONCAT('%', #{param.transactionNo}, '%')
AND TRANSACTION_TYPE = #{param.transactionType}
AND TRANSACTION_DATE >= #{param.transactionDateStart}
AND TRANSACTION_DATE <= #{param.transactionDateEnd}
AND SOURCE_SYSTEM = #{param.sourceSystem}
AND TRANSACTION_STATUS = #{param.transactionStatus}
ORDER BY TRANSACTION_DATE DESC, TRANSACTION_NO ASC

SELECT * FROM T_BUSINESS_TRANSACTION 
WHERE IS_DELETED = 0 
AND TRANSACTION_NO = #{transactionNo}
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}

    AND TRANSACTION_ID != #{excludeId}

LIMIT 1

